void swapnodes_next_two(NODE *p) {
    NODE *q1 = p->next;
    NODE *q2 = q1->next;
    NODE *q3 = q2->next;
    p->next  = q2;      /* p改指向原本的第二個節點 */
    q2->next = q1;      /* q2改指向原本的第一個節點 */
    q1->next = q3;      /* q1改指向原本q2之後的節點 */
}

void swapnodes_prev_next(NODE *p) {
    NODE *next = p->next;
    NODE *nextnext = next->next;
    NODE *prev = p;
    while (prev->next != p) prev = prev->next;      /* 繞行找前一個節點 */
    NODE *prevprev = p;
    while (prevprev->next != prev) prevprev = prevprev->next;
    prevprev->next = next;
    next->next = p;
    p->next = prev;
    prev->next = nextnext;
}

insert(pq, x)
struct queue *pq;
int x;
{
    NODEPTR p;
    p = getnode();          /* 配置一個新節點 */
    p->info = x;            /* 將資料x存入新節點 */
    p->next = NULL;         /* 新節點為佇列最後一個節點 */
    if (pq->front == NULL) {
        pq->front = p;      /* 佇列原本為空，新節點同時是第一個也是最後一個節點 */
        pq->rear = p;
    }
    else {
        pq->rear->next = p; /* 佇列原本非空，接在rear之後 */
        pq->rear = p;       /* 更新rear指標 */
    }
}

int binarySearch(int A[], int lo, int hi, int target) {
    if (lo > hi) {
        return -1;                    /* 搜尋範圍已空，找不到目標值 */
    }
    int mid = lo + (hi - lo) / 2;      /* 取中間位置（避免lo+hi溢位的寫法）*/
    if (A[mid] == target) {
        return mid;
    } else if (A[mid] < target) {
        return binarySearch(A, mid+1, hi, target);  /* 往右半部遞迴 */
    } else {
        return binarySearch(A, lo, mid-1, target);  /* 往左半部遞迴 */
    }
}

void inOrder(TreeNode *root) {
    TreeNode *curr = root;
    while (curr != NULL || !isEmpty()) {
        while (curr != NULL) {      /* 一路向左，沿途推入堆疊 */
            push(curr);
            curr = curr->left;
        }
        curr = pop();               /* 彈出並拜訪 */
        printf("%c ", curr->data);
        curr = curr->right;         /* 轉向右子樹 */
    }
}

int countTree(NODEPTR tree) {                 /* 計算節點總數 */
    if (tree == NULL) return 0;
    return 1 + countTree(tree->left) + countTree(tree->right);
}

int countLeaves(NODEPTR tree) {                /* 計算葉節點個數 */
    if (tree == NULL) return 0;
    if (tree->left == NULL && tree->right == NULL) return 1;
    return countLeaves(tree->left) + countLeaves(tree->right);
}

void swapTree(NODEPTR tree) {                  /* 左右子樹鏡像互換 */
    NODEPTR temp;
    if (tree == NULL) return;
    temp = tree->left;
    tree->left = tree->right;
    tree->right = temp;
    swapTree(tree->left);   /* 遞迴處理新的左子樹 */
    swapTree(tree->right);  /* 遞迴處理新的右子樹 */
}

void BuildHeap(int A[], int n) {
    for (int r = n/2; r >= 1; r--) {
        sift(A, r, n);
    }
}
